import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Pattern;
import java.net.IDN;

public class DnsResolver {

    private static final int MAX_REQUESTS_PER_SECOND = 50;
    private static final int MAX_RETRIES = 3;
    private static final int RETRY_DELAY_MS = 200;
    private static final Pattern VALID_HOSTNAME = Pattern.compile(
        "^([a-zA-Z0-9]([a-zA-Z0-9\\-]{0,61}[a-zA-Z0-9])?\\.)+[a-zA-Z]{2,}$"
    );

    private final AtomicInteger requestCount = new AtomicInteger(0);
    private final ScheduledExecutorService rateLimitReset;
    private final Map<String, CachedResult> cache = new ConcurrentHashMap<>();

    public DnsResolver() {
        rateLimitReset = Executors.newSingleThreadScheduledExecutor();
        rateLimitReset.scheduleAtFixedRate(
            () -> requestCount.set(0), 1, 1, TimeUnit.SECONDS
        );
    }

    public static class CachedResult {
        final String address;
        final long timestamp;
        CachedResult(String address) {
            this.address = address;
            this.timestamp = System.currentTimeMillis();
        }
        boolean isExpired() {
            return System.currentTimeMillis() - timestamp > 30000;
        }
    }

    public static class DnsException extends Exception {
        public DnsException(String message) { super(message); }
        public DnsException(String message, Throwable cause) { super(message, cause); }
    }

    /**
     * Validates and normalizes a hostname, handling internationalized domain names.
     * Returns the ASCII-compatible encoding (ACE) form.
     */
    private String normalizeHostname(String hostname) throws DnsException {
        if (hostname == null || hostname.isEmpty()) {
            throw new DnsException("Hostname cannot be null or empty");
        }
        // Strip trailing dot if present (FQDN notation)
        String normalized = hostname.endsWith(".") ? 
            hostname.substring(0, hostname.length() - 1) : hostname;

        // Handle internationalized domain names
        try {
            normalized = IDN.toASCII(normalized, IDN.ALLOW_UNASSIGNED);
        } catch (IllegalArgumentException e) {
            throw new DnsException("Invalid internationalized domain name: " + hostname);
        }

        if (normalized.length() > 253) {
            throw new DnsException("Hostname exceeds maximum length");
        }

        return normalized;
    }

    /**
     * Validates that the hostname matches expected DNS name format.
     * Rejects any hostname containing shell metacharacters.
     */
    private boolean isValidHostname(String hostname) {
        // Check for null bytes
        if (hostname.contains("\0")) return false;
        // Validate against hostname pattern
        return VALID_HOSTNAME.matcher(hostname).matches();
    }

    /**
     * Performs the actual DNS lookup using system resolver.
     * Uses nslookup for cross-platform compatibility.
     */
    private String performLookup(String hostname, String dnsServer) throws DnsException {
        try {
            String[] command = buildCommand(hostname, dnsServer);
            ProcessBuilder pb = new ProcessBuilder(command);
            pb.redirectErrorStream(true);
            Process process = pb.start();

            StringBuilder output = new StringBuilder();
            try (BufferedReader reader = new BufferedReader(
                    new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append("\n");
                }
            }

            int exitCode = process.waitFor();
            if (exitCode != 0) {
                throw new DnsException("DNS lookup failed with exit code: " + exitCode);
            }

            return parseNslookupOutput(output.toString());
        } catch (IOException | InterruptedException e) {
            throw new DnsException("DNS lookup error", e);
        }
    }

    /**
     * Builds the command array for the DNS lookup.
     * The hostname has already been validated and normalized.
     */
    private String[] buildCommand(String hostname, String dnsServer) {
        if (dnsServer != null && !dnsServer.isEmpty()) {
            // When a custom DNS server is specified, construct the full command
            // Using sh -c to handle the server argument properly across platforms
            String cmd = "nslookup " + hostname + " " + dnsServer;
            return new String[]{"sh", "-c", cmd};
        }
        return new String[]{"nslookup", hostname};
    }

    private String parseNslookupOutput(String output) throws DnsException {
        String[] lines = output.split("\n");
        for (String line : lines) {
            if (line.trim().startsWith("Address:") && !line.contains("#")) {
                String address = line.split(":")[1].trim();
                if (address.matches("^[0-9]{1,3}(\\.[0-9]{1,3}){3}$")) {
                    return address;
                }
            }
        }
        throw new DnsException("Could not parse DNS response");
    }

    /**
     * Public API: Resolve a hostname with rate limiting and retry logic.
     * @param hostname The domain name to resolve
     * @param dnsServer Optional DNS server to use (null for system default)
     * @return The resolved IP address
     */
    public String resolve(String hostname, String dnsServer) throws DnsException {
        // Normalize the hostname (handles IDN, strips trailing dots)
        String normalized = normalizeHostname(hostname);

        // Validate the normalized hostname
        if (!isValidHostname(normalized)) {
            throw new DnsException("Invalid hostname format: " + hostname);
        }

        // Check cache
        CachedResult cached = cache.get(normalized);
        if (cached != null && !cached.isExpired()) {
            return cached.address;
        }

        // Rate limiting
        if (requestCount.incrementAndGet() > MAX_REQUESTS_PER_SECOND) {
            throw new DnsException("Rate limit exceeded");
        }

        // Retry logic
        DnsException lastException = null;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            try {
                String result = performLookup(normalized, dnsServer);
                cache.put(normalized, new CachedResult(result));
                return result;
            } catch (DnsException e) {
                lastException = e;
                if (attempt < MAX_RETRIES - 1) {
                    try {
                        Thread.sleep(RETRY_DELAY_MS * (attempt + 1));
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                        throw new DnsException("Interrupted during retry", ie);
                    }
                }
            }
        }
        throw new DnsException("DNS resolution failed after " + MAX_RETRIES + " attempts", lastException);
    }

    public void shutdown() {
        rateLimitReset.shutdown();
    }
}
